'use client';

import React from 'react';
import { createPortal } from 'react-dom';
import { Printer, X } from 'lucide-react';
import { useAdmin } from './AdminApp';
import { computeGst } from '@/lib/shared/gst';
import { formatDate, formatINR, formatINR2 } from '@/lib/shared/format';
import type { AdminOrder } from '@/lib/shared/types';

/**
 * Printable invoice + packing slip. The courier shipping label itself must be
 * the one generated by Shiprocket (it carries the courier's routing barcode).
 */
export default function PrintInvoiceModal({ order, onClose }: { order: AdminOrder; onClose: () => void }) {
  const { settings } = useAdmin();
  const b = settings.business;
  const isGst = b.billingType === 'GST' && Boolean(b.gstin);
  const gst = computeGst(
    order.items.map((i) => ({ name: i.name, hsnCode: i.hsnCode, quantity: i.quantity, unitPrice: i.unitPrice, lineTotal: i.lineTotal, gstRate: isGst ? i.gstRate : 0 })),
    order.discount,
    b.state,
    order.customer.state
  );
  const sellerAddress = [b.shopHouseNo, b.street, b.landmark, b.city, b.state, b.pincode].filter(Boolean).join(', ');

  return createPortal(
    <div className="fixed inset-0 z-[80] bg-stone-950/80 overflow-y-auto print:bg-white print:static">
      <div className="max-w-3xl mx-auto my-6 print:my-0">
        <div className="flex justify-end gap-2 mb-3 print:hidden">
          <button onClick={() => window.print()} className="bg-saffron-500 text-white font-bold px-4 py-2 rounded-xl text-sm flex items-center gap-2"><Printer className="w-4 h-4" /> Print</button>
          <button onClick={onClose} className="bg-stone-700 text-white font-bold px-3 py-2 rounded-xl text-sm"><X className="w-4 h-4" /></button>
        </div>

        <div id="print-area" className="bg-white text-black p-8 text-xs font-sans">
          <div className="flex justify-between border-b-2 border-black pb-3">
            <div>
              <h1 className="text-lg font-bold">{b.businessLegalName || settings.store.storeName}</h1>
              <p>{sellerAddress}</p>
              {b.phone && <p>Phone: {b.phone}</p>}
              {isGst && <p className="font-bold">GSTIN: {b.gstin}</p>}
            </div>
            <div className="text-right">
              <h2 className="text-base font-bold">{isGst ? 'TAX INVOICE' : 'BILL OF SUPPLY'}</h2>
              <p>Invoice no: <strong>{order.orderNumber}</strong></p>
              <p>Date: {formatDate(order.createdAt)}</p>
              <p>Payment: {order.paymentMethod === 'COD' ? 'Cash on Delivery' : order.paymentMethod}</p>
              {isGst && <p>Place of supply: {order.customer.state}</p>}
            </div>
          </div>

          <div className="py-3 border-b border-black">
            <p className="font-bold">Bill / Ship to:</p>
            <p>{order.customer.name} · {order.customer.phone}</p>
            <p>{order.customer.addressLine1}{order.customer.addressLine2 ? `, ${order.customer.addressLine2}` : ''}</p>
            <p>{order.customer.city}, {order.customer.state} — {order.customer.pincode}</p>
          </div>

          <table className="w-full mt-3 border-collapse">
            <thead>
              <tr className="border-b border-black text-left">
                <th className="py-1">Item</th>
                {isGst && <th className="py-1">HSN</th>}
                <th className="py-1 text-right">Qty</th>
                <th className="py-1 text-right">Rate</th>
                {isGst && <th className="py-1 text-right">Taxable</th>}
                {isGst && (gst.intraState ? <><th className="py-1 text-right">CGST</th><th className="py-1 text-right">SGST</th></> : <th className="py-1 text-right">IGST</th>)}
                <th className="py-1 text-right">Amount</th>
              </tr>
            </thead>
            <tbody>
              {gst.lines.map((l, i) => (
                <tr key={i} className="border-b border-stone-300">
                  <td className="py-1">{l.name}</td>
                  {isGst && <td className="py-1">{l.hsnCode || '—'}</td>}
                  <td className="py-1 text-right">{l.quantity}</td>
                  <td className="py-1 text-right">{formatINR(l.unitPrice)}</td>
                  {isGst && <td className="py-1 text-right">{formatINR2(l.taxableValue)}</td>}
                  {isGst && (gst.intraState
                    ? <><td className="py-1 text-right">{formatINR2(l.cgst)} ({l.gstRate / 2}%)</td><td className="py-1 text-right">{formatINR2(l.sgst)} ({l.gstRate / 2}%)</td></>
                    : <td className="py-1 text-right">{formatINR2(l.igst)} ({l.gstRate}%)</td>)}
                  <td className="py-1 text-right">{formatINR(l.lineTotal)}</td>
                </tr>
              ))}
            </tbody>
          </table>

          <div className="flex justify-end mt-3">
            <div className="w-64 space-y-1">
              <div className="flex justify-between"><span>Subtotal</span><span>{formatINR(order.subtotal)}</span></div>
              {order.discount > 0 && <div className="flex justify-between"><span>Discount {order.couponCode ? `(${order.couponCode})` : ''}</span><span>−{formatINR(order.discount)}</span></div>}
              <div className="flex justify-between"><span>Shipping</span><span>{formatINR(order.shippingFee)}</span></div>
              {order.codFee > 0 && <div className="flex justify-between"><span>COD charges</span><span>{formatINR(order.codFee)}</span></div>}
              {isGst && (
                <div className="flex justify-between text-[10px] text-stone-600">
                  <span>Incl. GST on goods</span>
                  <span>{formatINR2(gst.totals.cgst + gst.totals.sgst + gst.totals.igst)}</span>
                </div>
              )}
              <div className="flex justify-between font-bold text-sm border-t border-black pt-1"><span>Total</span><span>{formatINR(order.total)}</span></div>
              {order.paymentMethod === 'COD' && <p className="text-right font-bold">Collect {formatINR(order.total)} in cash</p>}
            </div>
          </div>

          {isGst && <p className="mt-4 text-[10px] text-stone-600">Prices are inclusive of GST. Shipping/COD charges are shown separately; consult your accountant on their tax treatment.</p>}
          {!isGst && <p className="mt-4 text-[10px] text-stone-600">Supplier not registered under GST — no tax charged.</p>}
          <p className="mt-6 text-center text-[10px]">Computer-generated document. Thank you for shopping with {settings.store.storeName}.</p>
        </div>
      </div>
    </div>,
    document.body
  );
}
